CREATE PROCEDURE "AFL_CLEAR_UNNEED_PRIVILEGE" () LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  AS BEGIN     DECLARE cursor cur_list for         select * from objects where object_name in ( 'DA_APRIORI_RULE_PROC', 'PALLRWITHSEASONALADJUST_PROC', 'PALMULTIPLEFORECASTSMOOTHING_PROC');              for cur_row as cur_list     do         execute immediate 'revoke execute on "' || cur_row.schema_name || '"."' || cur_row.object_name || '" from AFL__SYS_AFL_AFLPAL_EXECUTE';         execute immediate 'revoke execute on "' || cur_row.schema_name || '"."' || cur_row.object_name || '" from AFL__SYS_AFL_AFLPAL_EXECUTE_WITH_GRANT_OPTION';     end for; end
